//! The files derived from config.toml for readers that cannot parse TOML:
//! the session (environment, screen), kanshi and netplan.

use std::io;
use std::net::Ipv4Addr;
use std::path::Path;

use crate::config::{ThinfloeConfig, xkb_options};
use crate::netfiles::{Wired, render_wifi, render_wired};
use crate::{atomic, kanshi, screentab};

/// First line of every generated file.
pub const HEADER: &str = "# Generated by the ThinFloe menu from ~/.config/thinfloe/config.toml. Edits here are lost.";

/// Generated files are tiny; anything bigger is not ours.
pub const MAX_BYTES: u64 = 64 * 1024;

/// A table of config.toml, named for the files it feeds.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Table {
    Keyboard,
    Screen,
    Status,
    Monitors,
    Network,
    Notice,
}

impl Table {
    /// The generated files this table feeds.
    pub fn files(self) -> &'static [&'static str] {
        match self {
            Table::Keyboard => &["environment"],
            Table::Screen => &["screen"],
            Table::Status | Table::Notice => &[],
            Table::Monitors => &["kanshi"],
            Table::Network => &["wifi.yaml", "ethernet.yaml"],
        }
    }
}

/// What the rendering needs besides the config.
#[derive(Debug, Clone, Default)]
pub struct Inputs {
    /// The text of the shipped `netfiles::DEFAULT_WIRED`.
    pub default_wired: String,
    pub netboot: bool,
}

fn ipv4_list(v: &[String]) -> Result<Vec<Ipv4Addr>, String> {
    v.iter()
        .map(|s| s.parse().map_err(|_| format!("WiFi DNS: not an IPv4 address: {s}")))
        .collect()
}

fn with_header(body: &str) -> String {
    format!("{HEADER}\n{body}")
}

/// The text of generated file `name`, or `None` when the file must be
/// absent.
pub fn render(cfg: &ThinfloeConfig, name: &str, inp: &Inputs) -> Result<Option<String>, String> {
    match name {
        "environment" => {
            let kb = &cfg.keyboard;
            Ok(Some(with_header(&format!(
                "XKB_DEFAULT_LAYOUT={}\nXKB_DEFAULT_VARIANT={}\nXKB_DEFAULT_OPTIONS={}\n",
                kb.layout,
                kb.variant,
                xkb_options(kb)
            ))))
        }
        "screen" => Ok(Some(with_header(&screentab::body(cfg.screen.idle_timeout)))),
        "kanshi" => {
            if let Some(kept) = &cfg.monitors.kept {
                return Ok(Some(with_header(kept)));
            }
            let profiles = cfg.monitors.to_profiles()?;
            if profiles.is_empty() {
                return Ok(None);
            }
            Ok(Some(format!("{HEADER}\n\n{}", kanshi::render(&profiles))))
        }
        "wifi.yaml" => {
            let n = &cfg.network;
            if let Some(kept) = &n.kept_wifi {
                return Ok(Some(with_header(kept)));
            }
            let nets = n.nets();
            if nets.is_empty() {
                return Ok(None);
            }
            let dns = ipv4_list(&n.wifi_dns)?;
            Ok(Some(with_header(&render_wifi(n.wifi_device.as_deref(), &nets, &dns))))
        }
        "ethernet.yaml" => {
            let n = &cfg.network;
            if let Some(kept) = &n.kept_wired {
                return Ok(Some(with_header(kept)));
            }
            let wired = n.wired()?;
            if inp.netboot {
                match &wired {
                    Wired::Static { .. } => return Err("A fixed address cannot be set on netboot.".into()),
                    w if !w.dns().is_empty() => return Err("DNS servers cannot be set on netboot.".into()),
                    _ => {}
                }
            }
            Ok(render_wired(&inp.default_wired, &wired)?.map(|t| with_header(&t)))
        }
        other => Err(format!("No generated file named {other}")),
    }
}

/// The file mode of generated file `name`: the netplan files hold
/// passwords.
pub fn mode_of(name: &str) -> u32 {
    match name {
        "wifi.yaml" | "ethernet.yaml" => 0o600,
        _ => 0o644,
    }
}

/// Bring `dir/name` to `body` (`None`: absent). True when the file
/// changed; an identical file is left alone, its mtime included.
pub fn write_if_changed(dir: &Path, name: &str, body: Option<&str>) -> io::Result<bool> {
    let path = dir.join(name);
    let old = atomic::read(&path, MAX_BYTES)?;
    match body {
        None if old.is_none() => Ok(false),
        None => atomic::remove(&path).map(|()| true),
        Some(b) if old.as_deref() == Some(b.as_bytes()) => Ok(false),
        Some(b) => atomic::write(&path, b.as_bytes(), mode_of(name)).map(|()| true),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::NetCfg;
    use crate::testdir::TestDir;
    use std::fs;
    use std::os::unix::fs::PermissionsExt;

    fn inp() -> Inputs {
        Inputs {
            default_wired: include_str!("../../../overlay/etc/netplan/ethernet.yaml").into(),
            netboot: false,
        }
    }

    fn two_nets(cfg: &mut ThinfloeConfig) {
        cfg.network.networks = vec![
            NetCfg {
                ssid: "home".into(),
                hidden: false,
                password: Some("secret-pw".into()),
            },
            NetCfg {
                ssid: "cafe".into(),
                hidden: true,
                password: None,
            },
        ];
        cfg.network.wifi_device = Some("wlan0".into());
    }

    #[test]
    fn environment_has_all_three_keys() {
        let t = render(&ThinfloeConfig::default(), "environment", &inp())
            .unwrap()
            .unwrap();
        assert_eq!(
            t,
            format!(
                "{HEADER}\nXKB_DEFAULT_LAYOUT=us\nXKB_DEFAULT_VARIANT=\nXKB_DEFAULT_OPTIONS=compose:ralt,ctrl:nocaps\n"
            )
        );
    }

    #[test]
    fn screen_file_reads_back() {
        let mut cfg = ThinfloeConfig::default();
        cfg.screen.idle_timeout = 900;
        let t = render(&cfg, "screen", &inp()).unwrap().unwrap();
        assert!(t.starts_with(HEADER));
        assert_eq!(screentab::parse_idle(&t), Some(900));
    }

    #[test]
    fn kanshi_file_parses_back() {
        use crate::heads::Mode;
        use crate::heads::Rotation;
        use crate::kanshi::{OutputSet, Place, Profile};
        let profiles = vec![Profile {
            outputs: vec![OutputSet {
                criteria: "eDP-1".into(),
                enabled: true,
                mode: Mode {
                    w: 1920,
                    h: 1080,
                    refresh_mhz: 60000,
                    preferred: false,
                },
                rotation: Rotation::Normal,
                place: Place::Origin,
            }],
            menu_output: None,
        }];
        let mut cfg = ThinfloeConfig::default();
        assert_eq!(render(&cfg, "kanshi", &inp()).unwrap(), None);
        cfg.monitors = crate::config::MonitorsCfg::from_profiles(&profiles);
        let t = render(&cfg, "kanshi", &inp()).unwrap().unwrap();
        assert_eq!(kanshi::parse(&t).unwrap(), profiles);
    }

    #[test]
    fn netplan_files_from_the_network_table() {
        let mut cfg = ThinfloeConfig::default();
        assert_eq!(render(&cfg, "wifi.yaml", &inp()).unwrap(), None);
        assert_eq!(render(&cfg, "ethernet.yaml", &inp()).unwrap(), None);
        two_nets(&mut cfg);
        let w = render(&cfg, "wifi.yaml", &inp()).unwrap().unwrap();
        assert_eq!(
            w,
            format!("{HEADER}\n{}", render_wifi(Some("wlan0"), &cfg.network.nets(), &[]))
        );
        cfg.network.set_wired(&Wired::Static {
            address: "10.0.0.5".parse().unwrap(),
            prefix: 24,
            gateway: None,
            dns: vec![],
        });
        let e = render(&cfg, "ethernet.yaml", &inp()).unwrap().unwrap();
        assert!(e.starts_with(&format!("{HEADER}\n")));
        assert!(e.contains("10.0.0.5/24"));
    }

    #[test]
    fn netboot_refuses_a_fixed_address() {
        let mut cfg = ThinfloeConfig::default();
        cfg.network.set_wired(&Wired::Static {
            address: "10.0.0.5".parse().unwrap(),
            prefix: 24,
            gateway: None,
            dns: vec![],
        });
        let mut i = inp();
        i.netboot = true;
        assert!(render(&cfg, "ethernet.yaml", &i).is_err());
    }

    #[test]
    fn kept_text_is_written_verbatim_under_the_header() {
        let mut cfg = ThinfloeConfig::default();
        cfg.network.kept_wifi = Some("network:\n  version: 2\n".into());
        cfg.network.kept_wired = Some("by hand\n".into());
        cfg.monitors.kept = Some("profile { output * enable }\n".into());
        assert_eq!(
            render(&cfg, "wifi.yaml", &inp()).unwrap().unwrap(),
            format!("{HEADER}\nnetwork:\n  version: 2\n")
        );
        assert_eq!(
            render(&cfg, "ethernet.yaml", &inp()).unwrap().unwrap(),
            format!("{HEADER}\nby hand\n")
        );
        assert_eq!(
            render(&cfg, "kanshi", &inp()).unwrap().unwrap(),
            format!("{HEADER}\nprofile {{ output * enable }}\n")
        );
    }

    #[test]
    fn write_if_changed_leaves_an_equal_file_alone() {
        let d = TestDir::new("generated", "changed");
        assert!(write_if_changed(&d, "screen", Some("a\n")).unwrap());
        let before = fs::metadata(d.join("screen")).unwrap().modified().unwrap();
        std::thread::sleep(std::time::Duration::from_millis(20));
        assert!(!write_if_changed(&d, "screen", Some("a\n")).unwrap());
        assert_eq!(fs::metadata(d.join("screen")).unwrap().modified().unwrap(), before);
        assert!(write_if_changed(&d, "screen", None).unwrap());
        assert!(!d.join("screen").exists());
        assert!(!write_if_changed(&d, "screen", None).unwrap());
    }

    #[test]
    fn netplan_files_are_0600() {
        let d = TestDir::new("generated", "mode");
        write_if_changed(&d, "wifi.yaml", Some("x\n")).unwrap();
        write_if_changed(&d, "screen", Some("x\n")).unwrap();
        assert_eq!(
            fs::metadata(d.join("wifi.yaml")).unwrap().permissions().mode() & 0o777,
            0o600
        );
        assert_eq!(
            fs::metadata(d.join("screen")).unwrap().permissions().mode() & 0o777,
            0o644
        );
    }

    #[test]
    fn tables_name_their_files() {
        assert_eq!(Table::Network.files(), ["wifi.yaml", "ethernet.yaml"]);
        assert!(Table::Status.files().is_empty());
    }
}
